style.css:
/* Operation: Island Storm — Roblox */
:root {
  /* Swap these colors to customize the theme */
  --my-olive: #526044;
  --my-dark: #171d19;
  --my-panel: #242d27;
  --my-text: #dce3d8;
  --my-accent: #a5b68b;
}

/* dark tactical atmosphere */
body {
  background: linear-gradient(135deg, #111914, #29372d, #151c18) !important;
  color: var(--my-text) !important;
  font-family: Arial, sans-serif !important;
}

/* tactical green links */
a {
  color: var(--my-accent) !important;
}

/* dark buttons */
button {
  background-color: var(--my-olive) !important;
  color: white !important;
  border: 1px solid #78876a !important;
  border-radius: 5px !important;
}

/* darker input fields */
input {
  background-color: var(--my-panel) !important;
  color: white !important;
  border: 1px solid #526044 !important;
}
